mapper.select:
SELECT CODE_ID, GROUP_CODE, CODE, CODE_NAME, PARENT_CODE_ID, SORT_ORDER, USE_YN FROM T_CODE
AND GROUP_CODE = #{group_code}
AND PARENT_CODE_ID = #{parent_code_id}
AND USE_YN = #{use_yn}
AND (CODE LIKE '%' || #{keyword} || '%' OR CODE_NAME LIKE '%' || #{keyword} || '%')
ORDER BY SORT_ORDER ASC

mapper.update:
UPDATE T_CODE
CODE = #{code}, CODE_NAME = #{code_name}, SORT_ORDER = #{sort_order}, USE_YN = #{use_yn}, MOD_ID = 'ADMIN', MOD_DT = SYSDATE
WHERE CODE_ID = #{code_id}
